class Solution {
public:
    int maxIncreasingGroups(vector<int>& usageLimits) {
        sort(usageLimits.begin(), usageLimits.end());
        long long total = 0;
        long long k = 0;          // groups built so far
        long long need = 1;       // total usage required for k+1 groups
        for (int v : usageLimits) {
            total += v;
            if (total >= need) {
                ++k;
                need += k + 1;    // next group needs (k+1) more
            }
        }
        return (int)k;
    }
};
